import type { Question, StudyModule } from "../module-types";

// ---------- FLU-01: Fluid Properties and Statics ----------

const lessonsProps=[
{title:"Density, specific weight, and specific gravity",body:"Density ρ is mass per unit volume; specific weight γ=ρg is weight per unit volume. Specific gravity SG=ρ/ρwater compares a fluid to water (ρwater≈1000 kg/m³ at 4°C), so ρfluid=SG×1000 kg/m³."},
{title:"Hydrostatic pressure",body:"In a static fluid, gauge pressure increases linearly with depth: p=ρgh, measured straight down from the free surface. Pressure at a point does not depend on the shape of the container, only on depth and fluid density."},
{title:"Manometers",body:"Walk a manometer from one open end to the other: add ρgh for every fluid column you descend, subtract ρgh for every column you ascend. For a fluid of specific gravity SG relative to water, use ρ=SG×1000 kg/m³ in each term."},
{title:"Buoyancy and submerged surfaces",body:"Archimedes' principle: the buoyant force equals the weight of fluid displaced, Fb=ρfluid g Vdisplaced, acting upward through the centroid of the displaced volume. The hydrostatic force on a submerged plane surface is F=ρg hc A, where hc is the depth of the surface's centroid."}
];

const flashcardsProps=[
{front:"Specific weight",back:"γ=ρg",note:"Use g=9.81 m/s² unless told otherwise."},
{front:"Specific gravity",back:"SG=ρfluid/ρwater",note:"ρwater=1000 kg/m³ at 4°C — the reference, not the answer."},
{front:"Hydrostatic pressure",back:"p=ρgh (gauge)",note:"h is measured vertically down from the free surface, not along a slanted path."},
{front:"Manometer rule",back:"Descending adds ρgh; ascending subtracts ρgh",note:"Track each fluid segment separately if densities differ."},
{front:"Archimedes' principle",back:"Fb=ρfluid g Vdisplaced",note:"Use the displaced fluid's density, not the object's density."},
{front:"Floating object submerged fraction",back:"Vsub/Vtotal=SGobject/SGfluid",note:"Not just SGobject — divide by the fluid's SG too."},
{front:"Force on a submerged plane surface",back:"F=ρg hc A",note:"hc is the centroid depth, not the maximum or minimum depth."},
{front:"Newton's law of viscosity",back:"τ=μ(du/dy)",note:"Convert every length to meters before dividing."}
];

const questionsProps:Question[]=[
{id:"FLU01-Q01",skill:"Specific gravity",difficulty:"Easy",prompt:"An oil has specific gravity 0.85. Find its density (ρwater=1000 kg/m³).",choices:["750 kg/m³","850 kg/m³","950 kg/m³","1000 kg/m³"],answer:1,explanation:"The oil's density is 850 kg/m³.",solution:"Step 1 — Use ρ=SG×ρwater.\nStep 2 — Substitute: ρ=0.85×1000.\nStep 3 — ρ=850 kg/m³.\nFinal answer: 850 kg/m³.",trap:"750 kg/m³ comes from an arithmetic slip (0.75×1000) rather than using the given SG of 0.85.",repair:"Multiply the given SG directly by 1000 kg/m³ — don't round or substitute a different value."},
{id:"FLU01-Q02",skill:"Specific weight",difficulty:"Easy",prompt:"Find the specific weight of water at standard conditions (ρ=1000 kg/m³, g=9.81 m/s²).",choices:["9.81 kN/m³","1000 kN/m³","981 kN/m³","0.981 kN/m³"],answer:0,explanation:"The specific weight of water is 9.81 kN/m³.",solution:"Step 1 — Use γ=ρg.\nStep 2 — Substitute: γ=1000×9.81=9810 N/m³.\nStep 3 — Convert to kN: 9810 N/m³=9.81 kN/m³.\nFinal answer: 9.81 kN/m³.",trap:"1000 kN/m³ comes from reporting the density value directly instead of multiplying by g and converting units.",repair:"Specific weight requires multiplying density by g — density alone is not specific weight."},
{id:"FLU01-Q03",skill:"Hydrostatic pressure",difficulty:"Medium",prompt:"Find the gauge pressure at a depth of 8 m in a tank of water (ρ=1000 kg/m³).",choices:["78.5 kPa","8.0 kPa","7.85 kPa","784.8 kPa"],answer:0,explanation:"The gauge pressure is about 78.5 kPa.",solution:"Step 1 — Use p=ρgh.\nStep 2 — Substitute: p=1000×9.81×8.\nStep 3 — p=78480 Pa.\nStep 4 — Convert: 78480 Pa=78.5 kPa.\nFinal answer: 78.5 kPa.",trap:"8.0 kPa comes from computing p=ρh and forgetting to multiply by g.",repair:"Hydrostatic pressure always includes g: p=ρgh, not p=ρh."},
{id:"FLU01-Q04",skill:"Manometry",difficulty:"Medium",prompt:"A mercury manometer (SG=13.6) is connected to a gas tank. The mercury column is 0.30 m higher on the open side than on the tank side. Find the gauge pressure of the gas.",choices:["40.0 kPa","2.94 kPa","133 kPa","4.00 kPa"],answer:0,explanation:"The gas gauge pressure is about 40.0 kPa.",solution:"Step 1 — The gas pressure equals the mercury column's pressure: p=ρHg g h.\nStep 2 — ρHg=SG×1000=13.6×1000=13600 kg/m³.\nStep 3 — p=13600×9.81×0.30.\nStep 4 — p=13600×9.81=133416; ×0.30=40024.8 Pa.\nFinal answer: 40.0 kPa.",trap:"2.94 kPa comes from using water's density instead of mercury's, ignoring the manometer fluid's specific gravity.",repair:"Always convert the manometer fluid's SG into an actual density (SG×1000 kg/m³) before applying p=ρgh."},
{id:"FLU01-Q05",skill:"Buoyancy — floating fraction",difficulty:"Medium",prompt:"An iceberg (SG=0.92) floats in seawater (SG=1.025). What fraction of its volume is submerged?",choices:["89.8%","92.0%","10.2%","102.5%"],answer:0,explanation:"About 89.8% of the iceberg's volume is submerged.",solution:"Step 1 — For a floating object, buoyant weight equals object weight: ρfluid g Vsub=ρobject g Vtotal.\nStep 2 — So Vsub/Vtotal=SGobject/SGfluid.\nStep 3 — Substitute: 0.92/1.025.\nStep 4 — 0.92/1.025=0.8976.\nFinal answer: 89.8% submerged.",trap:"92.0% comes from reporting the iceberg's own SG directly, ignoring that it is floating in seawater (SG=1.025), not fresh water.",repair:"Submerged fraction is SGobject divided by SGfluid — always divide by the actual fluid's specific gravity, not just the object's."},
{id:"FLU01-Q06",skill:"Force on a submerged surface",difficulty:"Hard",prompt:"A rectangular gate 2 m wide and 3 m tall is submerged vertically in water with its top edge at the free surface. Find the resultant hydrostatic force on the gate.",choices:["88.3 kN","176.6 kN","58.9 kN","44.1 kN"],answer:0,explanation:"The resultant force is about 88.3 kN.",solution:"Step 1 — Use F=ρg hc A, where hc is the centroid depth.\nStep 2 — The gate spans 0 to 3 m, so hc=3/2=1.5 m.\nStep 3 — A=2×3=6 m².\nStep 4 — F=1000×9.81×1.5×6.\nStep 5 — F=9810×1.5=14715; ×6=88290 N.\nFinal answer: 88.3 kN.",trap:"176.6 kN comes from using the full depth (3 m) instead of the centroid depth (1.5 m) in F=ρg h A.",repair:"The force on a submerged plane surface uses the centroid depth, not the maximum depth — for a surface starting at the free surface, that's half the total depth."},
{id:"FLU01-Q07",skill:"Viscosity",difficulty:"Easy",prompt:"A Newtonian fluid (μ=0.001 Pa·s) fills a 2 mm gap between two parallel plates. The top plate moves at 1.5 m/s and the bottom is fixed. Find the shear stress in the fluid.",choices:["0.75 Pa","0.00075 Pa","750 Pa","0.0015 Pa"],answer:0,explanation:"The shear stress is 0.75 Pa.",solution:"Step 1 — Use τ=μ(du/dy), with a linear velocity profile so du/dy=V/gap.\nStep 2 — Convert the gap to meters: 2 mm=0.002 m.\nStep 3 — du/dy=1.5/0.002=750 s⁻¹.\nStep 4 — τ=0.001×750=0.75 Pa.\nFinal answer: 0.75 Pa.",trap:"0.00075 Pa comes from leaving the gap as 2 (millimeters) instead of converting to 0.002 (meters), giving du/dy=1.5/2=0.75 s⁻¹.",repair:"Convert every length to meters before dividing — mixing mm and m silently shrinks du/dy by a factor of 1000."},
{id:"FLU01-Q08",skill:"Buoyancy — apparent weight",difficulty:"Medium",prompt:"A steel block (ρ=7800 kg/m³, V=0.02 m³) hangs fully submerged in water from a scale. Find the tension in the supporting cable.",choices:["1334 N","1530 N","196 N","1727 N"],answer:0,explanation:"The cable tension is about 1334 N.",solution:"Step 1 — Weight: W=ρblock V g=7800×0.02×9.81=1530.4 N.\nStep 2 — Buoyant force: Fb=ρwater V g=1000×0.02×9.81=196.2 N.\nStep 3 — Tension equals weight minus buoyancy: T=W−Fb.\nStep 4 — T=1530.4−196.2=1334.2 N.\nFinal answer: 1334 N.",trap:"1727 N comes from adding the buoyant force to the weight instead of subtracting it.",repair:"Buoyancy always opposes gravity on a submerged object — subtract it from the dry weight to get apparent weight."},
{id:"FLU01-Q09",skill:"Layered fluid pressure",difficulty:"Hard",prompt:"A tank holds a 2 m layer of oil (SG=0.8) floating on a 3 m layer of water. Find the gauge pressure at the bottom of the tank.",choices:["45.1 kPa","49.1 kPa","39.2 kPa","15.7 kPa"],answer:0,explanation:"The gauge pressure at the bottom is about 45.1 kPa.",solution:"Step 1 — Sum the pressure contribution of each layer: p=ρoil g holl+ρwater g hwater.\nStep 2 — ρoil=0.8×1000=800 kg/m³.\nStep 3 — poil=800×9.81×2=15696 Pa.\nStep 4 — pwater=1000×9.81×3=29430 Pa.\nStep 5 — Total: 15696+29430=45126 Pa.\nFinal answer: 45.1 kPa.",trap:"49.1 kPa comes from treating the entire 5 m column as water, ignoring that the top 2 m is lower-density oil.",repair:"In layered fluids, compute each layer's pressure contribution with its own density and add them — never use one density for the whole depth."},
{id:"FLU01-Q10",skill:"Differential manometry",difficulty:"Hard",prompt:"A mercury (SG=13.6) differential manometer connects two points in a horizontal water pipe at the same elevation. The mercury deflection is 0.20 m. Find the pressure difference between the two points.",choices:["24.7 kPa","26.7 kPa","12.4 kPa","19.6 kPa"],answer:0,explanation:"The pressure difference is about 24.7 kPa.",solution:"Step 1 — For a differential manometer with the pipe fluid also filling the legs, the water columns above the mercury cancel, leaving Δp=(ρHg−ρwater)g h.\nStep 2 — ρHg=13.6×1000=13600 kg/m³.\nStep 3 — Δp=(13600−1000)×9.81×0.20.\nStep 4 — 12600×9.81=123606; ×0.20=24721.2 Pa.\nFinal answer: 24.7 kPa.",trap:"26.7 kPa comes from using the full mercury density (13600 kg/m³) instead of the density difference between mercury and the water already filling the legs.",repair:"A differential manometer measures with the density difference (ρmanometer−ρpipe fluid), not the manometer fluid's density alone."}
];

export const fluidPropertiesModule:StudyModule={id:"FLU-01",subjectId:"fluid-mechanics",sectionId:"fluid-properties",title:"Fluid Properties and Statics",lessons:lessonsProps,flashcards:flashcardsProps,questions:questionsProps};

// ---------- FLU-02: Continuity and Control Volumes ----------

const lessonsCont=[
{title:"Conservation of mass",body:"For a control volume, mass in must equal mass out at steady state: Σṁin=Σṁout, where ṁ=ρAV. This holds regardless of how complex the internal geometry is, as long as the boundary is fixed and flow is steady."},
{title:"Incompressible continuity",body:"When density is constant, mass conservation reduces to A1V1=A2V2 between any two sections of a streamtube. A smaller cross-sectional area means a proportionally higher velocity — note the relationship uses area, so V scales with (D1/D2)², not D1/D2."},
{title:"Multi-port control volumes",body:"At a junction with several inlets and outlets, sum every inlet mass flow rate and set it equal to the sum of every outlet mass flow rate. Don't add a flow rate on the wrong side of the balance — direction (in vs. out) matters, not just magnitude."},
{title:"Volumetric vs. mass flow rate",body:"Volumetric flow rate Q=AV (m³/s) is convenient when density is constant; mass flow rate ṁ=ρQ (kg/s) is required whenever density changes between sections, such as in compressible flow or when fluids of different density mix."}
];

const flashcardsCont=[
{front:"Continuity (incompressible)",back:"A1V1=A2V2",note:"Only valid when density is the same at both sections."},
{front:"Mass flow rate",back:"ṁ=ρAV",note:"Units: kg/s. Use consistent SI units throughout."},
{front:"General steady mass balance",back:"Σṁin=Σṁout",note:"Works for any number of inlets/outlets, compressible or not."},
{front:"Volumetric flow rate",back:"Q=AV=ṁ/ρ",note:"Units: m³/s."},
{front:"Area–velocity scaling",back:"V2=V1(A1/A2)=V1(D1/D2)²",note:"Diameter ratio must be squared to get the area ratio."},
{front:"Unsteady tank balance",back:"dVtank/dt=Qin−Qout",note:"Divide by tank cross-sectional area to get the rate of level change."},
{front:"Pipe cross-sectional area",back:"A=πD²/4",note:"Use the radius-squared form (πr²) only if you're given radius, not diameter."}
];

const questionsCont:Question[]=[
{id:"FLU02-Q01",skill:"Mass flow rate",difficulty:"Easy",prompt:"Water (ρ=1000 kg/m³) flows through a 0.1 m diameter pipe at 2 m/s. Find the mass flow rate.",choices:["15.7 kg/s","7.85 kg/s","31.4 kg/s","1.57 kg/s"],answer:0,explanation:"The mass flow rate is about 15.7 kg/s.",solution:"Step 1 — Find the pipe area: A=πD²/4=π(0.1)²/4=0.007854 m².\nStep 2 — Use ṁ=ρAV.\nStep 3 — ṁ=1000×0.007854×2.\nStep 4 — ṁ=15.71 kg/s.\nFinal answer: 15.7 kg/s.",trap:"7.85 kg/s comes from computing ρA correctly but forgetting to multiply by the velocity.",repair:"Mass flow rate needs all three factors: density, area, AND velocity — check that you used every given value."},
{id:"FLU02-Q02",skill:"Volumetric flow rate",difficulty:"Easy",prompt:"Find the volumetric flow rate of a fluid moving at 3 m/s through a 0.2 m diameter pipe.",choices:["0.0943 m³/s","0.0314 m³/s","0.1885 m³/s","0.600 m³/s"],answer:0,explanation:"The volumetric flow rate is about 0.0943 m³/s.",solution:"Step 1 — Find the area: A=πD²/4=π(0.2)²/4=0.03142 m².\nStep 2 — Use Q=AV.\nStep 3 — Q=0.03142×3.\nStep 4 — Q=0.0943 m³/s.\nFinal answer: 0.0943 m³/s.",trap:"0.0314 m³/s is just the pipe area — the velocity was never multiplied in.",repair:"Volumetric flow rate is area TIMES velocity, not area alone."},
{id:"FLU02-Q03",skill:"Continuity — velocity change",difficulty:"Medium",prompt:"Water flows at 2 m/s through a 0.15 m diameter pipe that necks down to 0.10 m diameter. Find the velocity in the smaller section.",choices:["4.5 m/s","3.0 m/s","2.0 m/s","6.75 m/s"],answer:0,explanation:"The velocity in the smaller section is 4.5 m/s.",solution:"Step 1 — Use continuity: V2=V1(D1/D2)².\nStep 2 — D1/D2=0.15/0.10=1.5.\nStep 3 — (1.5)²=2.25.\nStep 4 — V2=2×2.25=4.5 m/s.\nFinal answer: 4.5 m/s.",trap:"3.0 m/s comes from scaling velocity by the diameter ratio directly (1.5×2) instead of by the squared area ratio.",repair:"Continuity scales with the AREA ratio — always square the diameter ratio before multiplying."},
{id:"FLU02-Q04",skill:"Compressible continuity",difficulty:"Medium",prompt:"Air enters a duct with ρ1=1.2 kg/m³, A1=0.5 m², V1=10 m/s and leaves where ρ2=0.8 kg/m³, A2=0.4 m². Find the exit velocity.",choices:["18.75 m/s","12.50 m/s","8.00 m/s","6.00 m/s"],answer:0,explanation:"The exit velocity is 18.75 m/s.",solution:"Step 1 — Apply mass conservation: ρ1A1V1=ρ2A2V2.\nStep 2 — Left side: 1.2×0.5×10=6 kg/s.\nStep 3 — Solve for V2: V2=6/(0.8×0.4)=6/0.32.\nStep 4 — V2=18.75 m/s.\nFinal answer: 18.75 m/s.",trap:"12.50 m/s comes from using the incompressible form A1V1=A2V2 and ignoring that the density changes between sections.",repair:"When density differs between sections, you must use ρ1A1V1=ρ2A2V2 — the simpler A1V1=A2V2 only applies when ρ is constant."},
{id:"FLU02-Q05",skill:"Junction mass balance",difficulty:"Medium",prompt:"A pipe carrying 0.5 m³/s splits into two branches. Branch A carries 0.2 m³/s. Find the flow rate in branch B.",choices:["0.3 m³/s","0.7 m³/s","0.2 m³/s","0.5 m³/s"],answer:0,explanation:"Branch B carries 0.3 m³/s.",solution:"Step 1 — Steady mass balance: Qin=QA+QB.\nStep 2 — Solve for QB: QB=Qin−QA.\nStep 3 — QB=0.5−0.2.\nFinal answer: 0.3 m³/s.",trap:"0.7 m³/s comes from adding the branch flow to the inlet flow instead of subtracting it out.",repair:"An outlet branch flow rate is found by subtracting it from the inlet total, not adding to it."},
{id:"FLU02-Q06",skill:"Unsteady control volume",difficulty:"Medium",prompt:"A tank with a 2 m² cross-sectional area receives water at 0.05 m³/s while simultaneously draining at 0.02 m³/s. Find the rate at which the water level rises.",choices:["0.015 m/s","0.035 m/s","0.025 m/s","0.060 m/s"],answer:0,explanation:"The water level rises at 0.015 m/s.",solution:"Step 1 — Net volume accumulation rate: dV/dt=Qin−Qout.\nStep 2 — dV/dt=0.05−0.02=0.03 m³/s.\nStep 3 — Rate of level rise: dh/dt=(dV/dt)/A.\nStep 4 — dh/dt=0.03/2=0.015 m/s.\nFinal answer: 0.015 m/s.",trap:"0.035 m/s comes from adding the inflow and outflow rates instead of subtracting the outflow from the inflow.",repair:"Net accumulation is inflow MINUS outflow — draining removes volume, it doesn't add to it."},
{id:"FLU02-Q07",skill:"Continuity — nozzle exit velocity",difficulty:"Hard",prompt:"Water flows at 0.06 m³/s through a nozzle that reduces the pipe diameter from 100 mm to 40 mm. Find the exit velocity.",choices:["47.7 m/s","7.64 m/s","19.10 m/s","4.78 m/s"],answer:0,explanation:"The exit velocity is about 47.7 m/s.",solution:"Step 1 — Find the exit area: A2=π(0.04)²/4=0.0012566 m².\nStep 2 — Use Q=A2V2, so V2=Q/A2.\nStep 3 — V2=0.06/0.0012566.\nStep 4 — V2≈47.75 m/s.\nFinal answer: 47.7 m/s.",trap:"7.64 m/s comes from dividing the flow rate by the larger INLET area (0.007854 m²) instead of the exit area, giving the inlet velocity instead.",repair:"Match the flow rate to the area at the SAME section — exit velocity needs exit area, not inlet area."},
{id:"FLU02-Q08",skill:"Merging streams",difficulty:"Hard",prompt:"Two water streams merge into a single outlet pipe of diameter 0.10 m. Inlet 1 is 0.08 m diameter at 3 m/s; inlet 2 is 0.05 m diameter at 4 m/s. Find the outlet velocity.",choices:["2.92 m/s","7.00 m/s","3.50 m/s","1.46 m/s"],answer:0,explanation:"The outlet velocity is about 2.92 m/s.",solution:"Step 1 — Find each inlet flow rate: Q1=A1V1=π(0.08)²/4×3=0.005027×3=0.01508 m³/s.\nStep 2 — Q2=A2V2=π(0.05)²/4×4=0.001963×4=0.007854 m³/s.\nStep 3 — Total outlet flow: Q3=Q1+Q2=0.01508+0.007854=0.02293 m³/s.\nStep 4 — Outlet area: A3=π(0.10)²/4=0.007854 m².\nStep 5 — V3=Q3/A3=0.02293/0.007854≈2.92 m/s.\nFinal answer: 2.92 m/s.",trap:"7.00 m/s comes from simply adding the two inlet velocities (3+4) instead of combining their flow rates and dividing by the outlet area.",repair:"Never add velocities from different pipes directly — convert each stream to a flow rate first, sum the flow rates, then divide by the receiving area."},
{id:"FLU02-Q09",skill:"Sizing a pipe from mass flow",difficulty:"Hard",prompt:"Water flows at a mass flow rate of 50 kg/s. To keep the velocity at or below 5 m/s, find the minimum required pipe diameter.",choices:["112.8 mm","56.4 mm","100.0 mm","225.6 mm"],answer:0,explanation:"The minimum pipe diameter is about 112.8 mm.",solution:"Step 1 — Find the minimum area: A=ṁ/(ρV)=50/(1000×5)=0.01 m².\nStep 2 — Solve A=πD²/4 for D: D=√(4A/π).\nStep 3 — D=√(4×0.01/π)=√(0.012732).\nStep 4 — D=0.1128 m=112.8 mm.\nFinal answer: 112.8 mm.",trap:"56.4 mm comes from correctly solving for the radius (r=√(A/π)=0.05642 m) but forgetting to double it to get the diameter.",repair:"After solving √(A/π), remember that gives the RADIUS — multiply by 2 to report the diameter."},
{id:"FLU02-Q10",skill:"Continuity concept",difficulty:"Easy",prompt:"For steady, incompressible flow in a single pipe with no branches, if the cross-sectional area decreases in the direction of flow, what happens to the fluid velocity?",choices:["It increases","It decreases","It stays the same","It depends only on the fluid's pressure"],answer:0,explanation:"Velocity increases where the area decreases, since A1V1=A2V2 must hold.",solution:"Step 1 — For incompressible flow, continuity requires A1V1=A2V2.\nStep 2 — If A2<A1, then V2 must be greater than V1 to keep the product constant.\nFinal answer: Velocity increases as the area decreases.",trap:"Answering 'it stays the same' ignores that continuity requires the AV product, not V alone, to remain constant.",repair:"Continuity fixes the product A×V, not V by itself — a smaller area always means a proportionally higher velocity for incompressible flow."}
];

export const continuityModule:StudyModule={id:"FLU-02",subjectId:"fluid-mechanics",sectionId:"continuity",title:"Continuity and Control Volumes",lessons:lessonsCont,flashcards:flashcardsCont,questions:questionsCont};

// ---------- FLU-03: Bernoulli and Energy Equation ----------

const lessonsEnergy=[
{title:"Bernoulli's equation",body:"For steady, incompressible, inviscid flow along a streamline: p/ρg+V²/2g+z=constant. It trades pressure head, velocity head, and elevation head — a speed-up must be paid for by a drop in pressure or elevation, with nothing else in the balance."},
{title:"Energy equation with losses",body:"Real flow has friction, so extend Bernoulli with a head-loss term: p1/ρg+V1²/2g+z1=p2/ρg+V2²/2g+z2+hL. hL is always positive and always subtracted from the upstream side (or added to the downstream side) — it never helps the flow."},
{title:"Stagnation and dynamic pressure",body:"Where a streamline is brought to rest (a stagnation point), all velocity head converts to pressure: p0=p+½ρV². A Pitot tube measures p0 directly; a Pitot-static tube measures the difference p0−p to back out V=√(2(p0−p)/ρ)."},
{title:"Venturi, orifice, and Torricelli's theorem",body:"Combine continuity (A1V1=A2V2) with Bernoulli to relate a measured pressure drop across a constriction to the flow rate — this is how a Venturi meter works. A free jet from a tank at depth h obeys Torricelli's theorem, V=√(2gh), which is Bernoulli applied between the free surface and the jet."}
];

const flashcardsEnergy=[
{front:"Bernoulli's equation",back:"p/ρg+V²/2g+z=const",note:"Requires steady, incompressible, frictionless flow along a streamline."},
{front:"Energy equation with head loss",back:"p1/ρg+V1²/2g+z1=p2/ρg+V2²/2g+z2+hL",note:"hL is always positive and goes on the downstream side."},
{front:"Dynamic pressure",back:"½ρV²",note:"This is the kinetic-energy-per-volume term, not the full stagnation pressure."},
{front:"Stagnation pressure",back:"p0=p+½ρV²",note:"What a simple Pitot tube reads directly."},
{front:"Torricelli's theorem",back:"V=√(2gh)",note:"h is the depth of fluid above the jet — don't drop the factor of 2."},
{front:"Pitot-static velocity",back:"V=√(2(p0−p)/ρ)",note:"Use the density of the flowing fluid, not the manometer fluid, here."},
{front:"Venturi meter principle",back:"Combine continuity + Bernoulli to relate Δp to Q",note:"A pressure drop at the throat is expected — it's not a loss, it's converted kinetic energy."}
];

const questionsEnergy:Question[]=[
{id:"FLU03-Q01",skill:"Dynamic pressure",difficulty:"Easy",prompt:"Air (ρ=1.2 kg/m³) flows at 20 m/s. Find its dynamic pressure.",choices:["240 Pa","480 Pa","120 Pa","24 Pa"],answer:0,explanation:"The dynamic pressure is 240 Pa.",solution:"Step 1 — Use dynamic pressure = ½ρV².\nStep 2 — Substitute: ½×1.2×20².\nStep 3 — 20²=400; ½×1.2=0.6.\nStep 4 — 0.6×400=240 Pa.\nFinal answer: 240 Pa.",trap:"480 Pa comes from forgetting the ½ factor and computing ρV² directly.",repair:"Dynamic pressure always includes the ½ factor: ½ρV², not ρV²."},
{id:"FLU03-Q02",skill:"Torricelli's theorem",difficulty:"Easy",prompt:"A tank holds water 5 m deep above a small orifice. Find the jet exit velocity (neglect losses).",choices:["9.90 m/s","7.00 m/s","98.1 m/s","4.95 m/s"],answer:0,explanation:"The exit velocity is about 9.90 m/s.",solution:"Step 1 — Use Torricelli's theorem: V=√(2gh).\nStep 2 — Substitute: V=√(2×9.81×5).\nStep 3 — 2×9.81×5=98.1.\nStep 4 — V=√98.1≈9.90 m/s.\nFinal answer: 9.90 m/s.",trap:"7.00 m/s comes from omitting the factor of 2, computing V=√(gh) instead of V=√(2gh).",repair:"Torricelli's theorem always includes the factor of 2 — it comes directly from Bernoulli's ½V² term."},
{id:"FLU03-Q03",skill:"Bernoulli — pressure at a second point",difficulty:"Medium",prompt:"In a pipe, point 1 (z1=0) has p1=300 kPa and V1=2 m/s; point 2 is 3 m higher (z2=3 m) with V2=5 m/s. Neglecting losses, find p2 (ρ=1000 kg/m³).",choices:["260.1 kPa","289.5 kPa","270.6 kPa","318.9 kPa"],answer:0,explanation:"The pressure at point 2 is about 260.1 kPa.",solution:"Step 1 — Bernoulli: p2=p1+½ρ(V1²−V2²)+ρg(z1−z2).\nStep 2 — Velocity term: ½×1000×(2²−5²)=500×(4−25)=−10500 Pa.\nStep 3 — Elevation term: 1000×9.81×(0−3)=−29430 Pa.\nStep 4 — p2=300000−10500−29430.\nFinal answer: 260.1 kPa.",trap:"289.5 kPa comes from correctly applying the velocity term but forgetting to include the elevation term entirely.",repair:"Bernoulli has three terms on each side — always check that you've carried pressure, velocity, AND elevation through the equation."},
{id:"FLU03-Q04",skill:"Venturi meter",difficulty:"Medium",prompt:"A horizontal Venturi meter reduces water from a 0.3 m diameter section (V1=1.5 m/s) to a 0.15 m diameter throat. Find the pressure drop between the two sections.",choices:["16.9 kPa","18.0 kPa","3.4 kPa","33.8 kPa"],answer:0,explanation:"The pressure drop is about 16.9 kPa.",solution:"Step 1 — Continuity: V2=V1(D1/D2)²=1.5×(0.3/0.15)²=1.5×4=6 m/s.\nStep 2 — Bernoulli (horizontal, so z terms cancel): Δp=½ρ(V2²−V1²).\nStep 3 — V2²−V1²=36−2.25=33.75.\nStep 4 — Δp=½×1000×33.75=16875 Pa.\nFinal answer: 16.9 kPa.",trap:"18.0 kPa comes from using V2² alone and forgetting to subtract the upstream velocity term V1².",repair:"Bernoulli's pressure drop uses the CHANGE in velocity head (V2²−V1²), not the throat velocity head by itself."},
{id:"FLU03-Q05",skill:"Energy equation with head loss",difficulty:"Medium",prompt:"Water drains from a large reservoir (surface at z1=20 m, V1≈0, p1=0 gauge) through a pipe to a nozzle exit at atmosphere (z2=0, p2=0 gauge, V2=15 m/s). Find the head loss between the two points.",choices:["8.53 m","20.0 m","11.47 m","31.47 m"],answer:0,explanation:"The head loss is about 8.53 m.",solution:"Step 1 — Energy equation: z1=V2²/2g+z2+hL (since p1=p2=0 and V1≈0).\nStep 2 — Velocity head: V2²/2g=225/19.62=11.47 m.\nStep 3 — Solve for hL: hL=z1−z2−V2²/2g=20−0−11.47.\nFinal answer: 8.53 m.",trap:"20.0 m comes from ignoring the exit velocity head entirely and treating the full elevation drop as head loss.",repair:"Some of the elevation drop always goes into kinetic energy at the exit — subtract the velocity head before calling the rest a loss."},
{id:"FLU03-Q06",skill:"Bernoulli assumptions",difficulty:"Easy",prompt:"Which of the following is NOT one of the assumptions required to apply Bernoulli's equation between two points on a streamline?",choices:["Steady flow","Incompressible flow","Frictionless (inviscid) flow","Turbulent flow"],answer:3,explanation:"Bernoulli requires steady, incompressible, frictionless flow along a streamline — turbulence is not part of the required assumptions.",solution:"Step 1 — Recall the derivation of Bernoulli's equation: it assumes steady flow, constant density, and no viscous losses along a streamline.\nStep 2 — Turbulence is a flow regime, not one of the required assumptions — real turbulent flows can still be approximated with Bernoulli away from regions of high friction.\nFinal answer: Turbulent flow is not a Bernoulli assumption.",trap:"Selecting 'frictionless flow' incorrectly assumes it isn't required, when inviscid flow is in fact one of the three core assumptions.",repair:"Memorize the three Bernoulli assumptions as a set: steady, incompressible, frictionless (along a streamline) — turbulence isn't on that list."},
{id:"FLU03-Q07",skill:"Pitot-static tube",difficulty:"Hard",prompt:"A Pitot-static tube in a water stream is connected to a mercury (SG=13.6) manometer that shows a 0.10 m deflection. Find the water velocity.",choices:["4.97 m/s","5.17 m/s","3.52 m/s","7.03 m/s"],answer:0,explanation:"The water velocity is about 4.97 m/s.",solution:"Step 1 — The manometer reads Δp=(ρHg−ρwater)g h, since water fills the tube legs above the mercury.\nStep 2 — Δp=(13600−1000)×9.81×0.10=12600×9.81×0.10=12360.6 Pa.\nStep 3 — Use V=√(2Δp/ρwater).\nStep 4 — V=√(2×12360.6/1000)=√24.72≈4.97 m/s.\nFinal answer: 4.97 m/s.",trap:"5.17 m/s comes from using the full mercury density (13600 kg/m³) in Δp instead of the density difference between mercury and the water already filling the tube legs.",repair:"A liquid-filled Pitot-static manometer measures with the DIFFERENTIAL density (ρmanometer−ρflowing fluid), just like any other differential manometer."},
{id:"FLU03-Q08",skill:"Orifice discharge coefficient",difficulty:"Hard",prompt:"A tank drains through a sharp-edged orifice of area 500 mm², located 2.5 m below the free surface. The discharge coefficient is Cd=0.61. Find the actual volumetric flow rate.",choices:["2.14 L/s","3.50 L/s","1.31 L/s","4.28 L/s"],answer:0,explanation:"The actual flow rate is about 2.14 L/s.",solution:"Step 1 — Ideal velocity from Torricelli: V=√(2gh)=√(2×9.81×2.5)=√49.05≈7.00 m/s.\nStep 2 — Ideal flow rate: Qideal=A V=0.0005×7.00=0.00350 m³/s=3.50 L/s.\nStep 3 — Actual flow rate: Qactual=Cd×Qideal=0.61×3.50.\nFinal answer: 2.14 L/s.",trap:"3.50 L/s comes from computing the ideal flow rate correctly but forgetting to apply the discharge coefficient Cd.",repair:"A real orifice always discharges less than the ideal (frictionless) prediction — multiply by Cd before reporting the actual flow rate."},
{id:"FLU03-Q09",skill:"Siphon pressure",difficulty:"Hard",prompt:"A siphon draws water from a reservoir (free surface at z=0) over a hump 1.5 m above the surface, discharging at a point 2 m below the surface. The tube has uniform diameter throughout. Find the gauge pressure at the hump.",choices:["-34.3 kPa","-14.7 kPa","34.3 kPa","-49.1 kPa"],answer:0,explanation:"The gauge pressure at the hump is about −34.3 kPa.",solution:"Step 1 — Exit velocity from Torricelli, using the 2 m total drop to the exit: V=√(2×9.81×2)=√39.24 m²/s².\nStep 2 — Since the tube has uniform diameter, the velocity at the hump equals the exit velocity, so V²/2g=39.24/19.62=2.0 m.\nStep 3 — Energy equation from surface (p=0,V≈0,z=0) to hump (z=1.5 m): 0=phump/ρg+2.0+1.5.\nStep 4 — phump/ρg=−3.5 m, so phump=1000×9.81×(−3.5)=−34335 Pa.\nFinal answer: −34.3 kPa (below atmospheric).",trap:"−14.7 kPa comes from including only the elevation rise to the hump and forgetting the velocity head term entirely.",repair:"The energy equation needs BOTH the elevation term and the velocity head at the hump — a siphon crest is low-pressure because of both effects together."},
{id:"FLU03-Q10",skill:"Stagnation pressure",difficulty:"Medium",prompt:"Air (ρ=1.225 kg/m³) with static pressure 101.325 kPa flows at 30 m/s. Find the stagnation pressure at a point where the flow is brought to rest.",choices:["101.88 kPa","102.43 kPa","100.77 kPa","0.55 kPa"],answer:0,explanation:"The stagnation pressure is about 101.88 kPa.",solution:"Step 1 — Use p0=p+½ρV².\nStep 2 — Dynamic pressure: ½×1.225×30²=½×1.225×900=551.25 Pa.\nStep 3 — p0=101325+551.25.\nFinal answer: 101.88 kPa.",trap:"100.77 kPa comes from subtracting the dynamic pressure instead of adding it.",repair:"At a stagnation point, kinetic energy converts fully into additional pressure — always ADD the dynamic pressure to the static pressure."}
];

export const energyModule:StudyModule={id:"FLU-03",subjectId:"fluid-mechanics",sectionId:"energy",title:"Bernoulli and Energy Equation",lessons:lessonsEnergy,flashcards:flashcardsEnergy,questions:questionsEnergy};

// ---------- FLU-04: Momentum Analysis ----------

const lessonsMomentum=[
{title:"Linear momentum equation",body:"For a steady control volume with uniform inlet/outlet velocity, ΣF=ṁ(Vout−Vin), applied as a vector equation. Apply it separately along each coordinate direction (ΣFx and ΣFy), then combine components at the end if a resultant is needed."},
{title:"Forces on bends and nozzles",body:"The force needed to anchor a pipe bend or nozzle must balance BOTH the rate of change of fluid momentum AND the net pressure force acting on the fluid at the inlet and outlet cross-sections. Skipping the pressure term is the single most common mistake in these problems."},
{title:"Jets on stationary plates",body:"When a jet strikes a stationary flat plate and splashes off sideways, the momentum component along the original jet axis drops to zero after impact, so the force on the plate is F=ṁV for a perpendicular jet, or F=ṁV sinθ for a jet striking at angle θ to the plate."},
{title:"Moving vanes",body:"For a vane moving at speed u, use the velocity relative to the vane (V−u), both for the mass flow rate that actually reaches the moving vane (ṁrel=ρA(V−u)) and for the momentum change the vane produces. Using the absolute jet velocity instead of the relative velocity is a common and costly error."}
];

const flashcardsMomentum=[
{front:"Linear momentum equation",back:"ΣF=ṁ(Vout−Vin)",note:"A vector equation — resolve into x and y components separately."},
{front:"Force on a stationary flat plate",back:"F=ṁV",note:"Valid when the jet's momentum along its original axis is fully destroyed."},
{front:"Force on a 180° vane (stationary)",back:"F=2ṁV",note:"Full reversal doubles the momentum change compared to a flat plate."},
{front:"Pipe bend anchoring force",back:"Momentum change + pressure force at each face",note:"Never drop the pressure term — it's often the larger contributor."},
{front:"Moving vane relative velocity",back:"Use (V−u) for both ṁ and ΔV",note:"u is the vane speed; V is the jet speed relative to the ground."},
{front:"Jet on inclined plate",back:"Fnormal=ṁV sinθ",note:"θ is measured from the plate, not from the jet's centerline."},
{front:"Vector momentum equation",back:"ΣFx=ṁ(Vout,x−Vin,x); ΣFy similarly",note:"Solve each axis independently, then combine with the Pythagorean theorem if needed."},
{front:"Jet propulsion thrust",back:"F=ṁexit Vexit−ṁinlet Vinlet",note:"Use the EXIT mass flow rate (inlet + any added fuel) for the exit momentum term."}
];

const questionsMomentum:Question[]=[
{id:"FLU04-Q01",skill:"Jet on a stationary plate",difficulty:"Easy",prompt:"A horizontal water jet with mass flow rate 10 kg/s and velocity 15 m/s strikes a stationary flat plate held perpendicular to the jet, splashing off sideways. Find the force on the plate.",choices:["150 N","75 N","300 N","1.5 N"],answer:0,explanation:"The force on the plate is 150 N.",solution:"Step 1 — For a perpendicular jet on a flat plate, the momentum along the jet axis drops to zero: F=ṁV.\nStep 2 — Substitute: F=10×15.\nFinal answer: 150 N.",trap:"75 N comes from an arithmetic slip — dividing the product by 2 instead of reporting ṁV directly.",repair:"Force on a flat plate from a perpendicular jet is simply F=ṁV — no factor of ½ or 2 belongs here."},
{id:"FLU04-Q02",skill:"Mass flow rate from geometry",difficulty:"Easy",prompt:"A nozzle with exit area 0.001 m² discharges water (ρ=1000 kg/m³) at 20 m/s. Find the mass flow rate.",choices:["20 kg/s","0.02 kg/s","2 kg/s","200 kg/s"],answer:0,explanation:"The mass flow rate is 20 kg/s.",solution:"Step 1 — Use ṁ=ρAV.\nStep 2 — Substitute: ṁ=1000×0.001×20.\nFinal answer: 20 kg/s.",trap:"0.02 kg/s comes from computing AV=0.001×20=0.02 and forgetting to multiply by the density.",repair:"Mass flow rate always includes density: ṁ=ρAV, not just AV."},
{id:"FLU04-Q03",skill:"Force on a turning vane",difficulty:"Medium",prompt:"A water jet with ṁ=15 kg/s and V=12 m/s enters a stationary vane horizontally and is turned 90° to leave vertically at the same speed. Find the magnitude of the resultant force on the vane.",choices:["254.6 N","180.0 N","360.0 N","127.3 N"],answer:0,explanation:"The resultant force is about 254.6 N.",solution:"Step 1 — Horizontal force: Fx=ṁ(Vin−0)=15×12=180 N.\nStep 2 — Vertical force: Fy=ṁ(Vout−0)=15×12=180 N.\nStep 3 — Combine as a vector: F=√(Fx²+Fy²)=√(180²+180²).\nStep 4 — F=180√2≈254.6 N.\nFinal answer: 254.6 N.",trap:"180.0 N reports only the horizontal (or vertical) component and ignores that the other component must be combined vectorially.",repair:"A 90° turn produces force components on BOTH axes — always combine them with the Pythagorean theorem for the resultant."},
{id:"FLU04-Q04",skill:"Force on a pipe bend",difficulty:"Hard",prompt:"A horizontal 180° return bend has a uniform 0.1 m diameter throughout. Water (ρ=1000 kg/m³) flows through at 5 m/s, and the gauge pressure is 150 kPa at both the inlet and outlet. Find the magnitude of the anchoring force needed to hold the bend in place.",choices:["2748.9 N","392.7 N","2356.2 N","1570.8 N"],answer:0,explanation:"The anchoring force is about 2748.9 N.",solution:"Step 1 — Area: A=π(0.1)²/4=0.007854 m²; mass flow rate: ṁ=ρAV=1000×0.007854×5=39.27 kg/s.\nStep 2 — Since the flow reverses 180°, the momentum term uses (V1+V2): Fmomentum=39.27×(5+5)=392.7 N.\nStep 3 — Both pressure faces push in the same net direction for a 180° bend: Fpressure=(p1+p2)A=(150000+150000)×0.007854=2356.2 N.\nStep 4 — Total force: F=392.7+2356.2.\nFinal answer: 2748.9 N.",trap:"392.7 N accounts for the momentum change only and completely omits the pressure force acting on the inlet and outlet faces.",repair:"Anchoring force on a bend always has two parts — momentum change AND net pressure force — never report the momentum term alone."},
{id:"FLU04-Q05",skill:"Force to accelerate flow in a nozzle",difficulty:"Medium",prompt:"A nozzle reduces a pipe from A1=0.005 m² to A2=0.001 m². Water (ρ=1000 kg/m³) enters at V1=4 m/s. Neglecting pressure forces, find the force exerted by the fluid on the nozzle.",choices:["320 N","480 N","400 N","80 N"],answer:0,explanation:"The force is 320 N.",solution:"Step 1 — Continuity: V2=V1(A1/A2)=4×(0.005/0.001)=4×5=20 m/s.\nStep 2 — Mass flow rate: ṁ=ρA1V1=1000×0.005×4=20 kg/s.\nStep 3 — Momentum equation: F=ṁ(V2−V1)=20×(20−4).\nFinal answer: 320 N.",trap:"480 N comes from using ṁ(V1+V2) — the formula for a 180° flow reversal — instead of ṁ(V2−V1) for flow continuing in the same direction.",repair:"Use ΔV=V2−V1 whenever flow continues in the same direction; only a full reversal calls for summing the velocities."},
{id:"FLU04-Q06",skill:"Force on a moving vane",difficulty:"Hard",prompt:"A water jet (ρ=1000 kg/m³, area 0.003 m²) moving at 30 m/s strikes a single vane moving away at 10 m/s in the same direction, deflecting the flow 180° relative to the vane. Find the force on the vane.",choices:["2400 N","5400 N","1200 N","2700 N"],answer:0,explanation:"The force on the vane is 2400 N.",solution:"Step 1 — Relative velocity: Vrel=V−u=30−10=20 m/s.\nStep 2 — Mass flow rate reaching the vane: ṁrel=ρA(V−u)=1000×0.003×20=60 kg/s.\nStep 3 — For a 180° reversal, the force is F=ṁrel×2×Vrel=60×2×20.\nFinal answer: 2400 N.",trap:"5400 N comes from using the jet's absolute velocity (30 m/s) instead of the velocity relative to the moving vane (20 m/s) in both the mass flow rate and the momentum change.",repair:"For a moving vane, always compute with the RELATIVE velocity (V−u) — the vane never 'sees' the jet's ground-frame speed."},
{id:"FLU04-Q07",skill:"Jet on an inclined plate",difficulty:"Medium",prompt:"A water jet with ṁ=12 kg/s and V=10 m/s strikes a flat plate inclined at 40° to the jet direction (frictionless along the plate). Find the force normal to the plate.",choices:["77.1 N","91.9 N","120.0 N","38.6 N"],answer:0,explanation:"The normal force is about 77.1 N.",solution:"Step 1 — For a jet striking a plate at angle θ from the plate surface, the normal force is Fn=ṁV sinθ.\nStep 2 — Substitute: Fn=12×10×sin40°.\nStep 3 — sin40°≈0.6428.\nStep 4 — Fn=120×0.6428≈77.1 N.\nFinal answer: 77.1 N.",trap:"91.9 N comes from using cosθ instead of sinθ, mixing up which trig function applies to the angle measured from the plate.",repair:"Sketch the angle carefully — for an angle measured from the plate surface, the normal (perpendicular) component uses sine, not cosine."},
{id:"FLU04-Q08",skill:"Control volume force from velocity change",difficulty:"Easy",prompt:"A control volume has a single inlet at 5 kg/s, 3 m/s and a single outlet at the same mass flow rate, 9 m/s, both horizontal and in the same direction. Find the net force required on the fluid.",choices:["30 N","60 N","45 N","6 N"],answer:0,explanation:"The net force is 30 N.",solution:"Step 1 — Use ΣF=ṁ(Vout−Vin).\nStep 2 — Substitute: F=5×(9−3).\nStep 3 — F=5×6.\nFinal answer: 30 N.",trap:"60 N comes from adding the velocities (9+3) instead of subtracting to find the change in velocity.",repair:"The momentum equation always uses the CHANGE in velocity (Vout−Vin), never the sum."},
{id:"FLU04-Q09",skill:"Jet propulsion thrust",difficulty:"Hard",prompt:"A jet engine takes in air at 50 kg/s with negligible inlet velocity and ejects exhaust gas (air plus injected fuel) at 51 kg/s at 500 m/s relative to the engine, with exit pressure equal to ambient. Find the thrust force.",choices:["25.5 kN","25.0 kN","26.0 kN","25.3 kN"],answer:0,explanation:"The thrust force is about 25.5 kN.",solution:"Step 1 — Use F=ṁexit Vexit−ṁinlet Vinlet.\nStep 2 — The inlet term is zero since inlet velocity is negligible.\nStep 3 — F=51×500−50×0=25500 N.\nFinal answer: 25.5 kN.",trap:"25.0 kN comes from using the inlet mass flow rate (50 kg/s) for the exit momentum term instead of the larger exhaust mass flow rate (51 kg/s), neglecting the added fuel mass.",repair:"The exit momentum term always uses the EXIT mass flow rate — remember that fuel addition makes the exhaust flow rate larger than the inlet air flow rate."},
{id:"FLU04-Q10",skill:"Force on a plate from a computed jet",difficulty:"Medium",prompt:"A nozzle with exit area 0.0025 m² discharges water (ρ=1000 kg/m³) at 12 m/s horizontally onto a stationary flat plate held perpendicular to the jet. Find the force on the plate.",choices:["360 N","30 N","180 N","720 N"],answer:0,explanation:"The force on the plate is 360 N.",solution:"Step 1 — Find the mass flow rate: ṁ=ρAV=1000×0.0025×12=30 kg/s.\nStep 2 — Apply F=ṁV for a perpendicular jet on a flat plate.\nStep 3 — F=30×12.\nFinal answer: 360 N.",trap:"30 N reports the mass flow rate itself (30 kg/s) instead of completing the final step of multiplying by the velocity to get the force.",repair:"Don't stop at computing ṁ — the force requires one more multiplication by V (F=ṁV)."}
];

export const momentumModule:StudyModule={id:"FLU-04",subjectId:"fluid-mechanics",sectionId:"momentum",title:"Momentum Analysis",lessons:lessonsMomentum,flashcards:flashcardsMomentum,questions:questionsMomentum};

// ---------- FLU-05: Internal Flow and Losses ----------

const lessonsInternal=[
{title:"Reynolds number",body:"Re=ρVD/μ=VD/ν is the ratio of inertial to viscous forces and determines the flow regime in a pipe. Always compute Re first — it decides which friction-factor formula applies before you calculate any head loss."},
{title:"Laminar vs. turbulent flow",body:"In a circular pipe, Re<~2300 is laminar (parabolic profile, f=64/Re exactly), while Re>~4000 is turbulent (flatter profile, f depends on both Re and relative roughness ε/D via the Moody chart or a correlation). Never assume a typical turbulent friction factor without checking Re first."},
{title:"Darcy-Weisbach equation",body:"Major (friction) head loss along a pipe is hf=f(L/D)(V²/2g), where f is the dimensionless Darcy friction factor. Keep L/D as a ratio (not D/L), and don't drop the factor of 2 in 2g."},
{title:"Minor losses",body:"Losses through fittings, valves, and bends are hminor=K(V²/2g), where K is an empirical loss coefficient specific to that component. In a system with several fittings in series, sum all the K values first, then multiply the total by V²/2g once."}
];

const flashcardsInternal=[
{front:"Reynolds number",back:"Re=ρVD/μ",note:"Dimensionless — check units carefully before dividing."},
{front:"Laminar threshold (pipe flow)",back:"Re≲2300 is laminar",note:"Re≳4000 is turbulent; between is the transition region."},
{front:"Laminar friction factor",back:"f=64/Re",note:"Re is in the denominator — don't invert the ratio."},
{front:"Darcy-Weisbach equation",back:"hf=f(L/D)(V²/2g)",note:"Use L/D, not D/L, and don't drop the factor of 2 in 2g."},
{front:"Minor loss formula",back:"hminor=K(V²/2g)",note:"Sum every K in the series system before multiplying by V²/2g."},
{front:"Total system head loss",back:"htotal=Σhmajor+Σhminor",note:"Add major (friction) and minor (fitting) losses together."},
{front:"Relative roughness",back:"ε/D controls f for turbulent flow",note:"Read from the Moody chart along with Re."},
{front:"Velocity head",back:"V²/2g",note:"The recurring building block in every head-loss formula."}
];

const questionsInternal:Question[]=[
{id:"FLU05-Q01",skill:"Reynolds number",difficulty:"Easy",prompt:"Water (ρ=1000 kg/m³, μ=0.001 Pa·s) flows at 2 m/s through a 0.05 m diameter pipe. Find the Reynolds number.",choices:["100,000","1,000","10,000","1,000,000"],answer:0,explanation:"The Reynolds number is 100,000.",solution:"Step 1 — Use Re=ρVD/μ.\nStep 2 — Numerator: 1000×2×0.05=100.\nStep 3 — Divide by μ: Re=100/0.001.\nFinal answer: 100,000.",trap:"10,000 comes from a decimal-place slip, dividing by 0.01 instead of the correct μ=0.001.",repair:"Double-check the number of zeros when dividing by a small viscosity value like 0.001 Pa·s."},
{id:"FLU05-Q02",skill:"Flow regime classification",difficulty:"Easy",prompt:"Water flows in a pipe with Reynolds number 1800. Classify the flow.",choices:["Laminar","Turbulent","Transitional","Choked"],answer:0,explanation:"Re=1800 is below the laminar threshold of about 2300, so the flow is laminar.",solution:"Step 1 — Compare Re to the standard pipe-flow thresholds: laminar below about 2300, turbulent above about 4000.\nStep 2 — Re=1800 is below 2300.\nFinal answer: Laminar flow.",trap:"Labeling it turbulent ignores that 1800 is well below the ~2300 laminar threshold for pipe flow.",repair:"Memorize the pipe-flow thresholds: Re≲2300 laminar, Re≳4000 turbulent."},
{id:"FLU05-Q03",skill:"Darcy-Weisbach head loss",difficulty:"Medium",prompt:"Water flows at 3 m/s through a 50 m long, 0.1 m diameter pipe with friction factor f=0.02. Find the friction head loss.",choices:["4.59 m","9.17 m","2.29 m","0.459 m"],answer:0,explanation:"The friction head loss is about 4.59 m.",solution:"Step 1 — Use hf=f(L/D)(V²/2g).\nStep 2 — L/D=50/0.1=500.\nStep 3 — V²/2g=9/19.62=0.4587.\nStep 4 — hf=0.02×500×0.4587.\nFinal answer: 4.59 m.",trap:"9.17 m comes from using V²/g instead of V²/2g, dropping the factor of 2 in the denominator.",repair:"The velocity head is always V²/(2g) — check that the 2 is included before multiplying."},
{id:"FLU05-Q04",skill:"Minor losses",difficulty:"Medium",prompt:"Water at 4 m/s flows through a system with a globe valve (K=10) and two 90° elbows (K=0.9 each). Find the total minor head loss.",choices:["9.62 m","8.89 m","1.47 m","10.36 m"],answer:0,explanation:"The total minor head loss is about 9.62 m.",solution:"Step 1 — Sum the loss coefficients: ΣK=10+0.9+0.9=11.8.\nStep 2 — Velocity head: V²/2g=16/19.62=0.8155 m.\nStep 3 — hminor=ΣK×(V²/2g)=11.8×0.8155.\nFinal answer: 9.62 m.",trap:"8.89 m comes from only counting one elbow (ΣK=10.9) instead of both 90° elbows in the series system.",repair:"Count every single fitting in the system when summing K — it's easy to lose track of a repeated component."},
{id:"FLU05-Q05",skill:"Laminar friction factor",difficulty:"Medium",prompt:"Oil flows in a pipe at Reynolds number 800 (laminar). Find the Darcy friction factor.",choices:["0.080","0.064","12.5","0.640"],answer:0,explanation:"The friction factor is 0.080.",solution:"Step 1 — For laminar pipe flow, use f=64/Re.\nStep 2 — Substitute: f=64/800.\nFinal answer: 0.080.",trap:"12.5 comes from inverting the ratio (Re/64=800/64=12.5) instead of computing 64/Re.",repair:"The laminar friction factor formula has Re in the denominator: f=64/Re, not Re/64."},
{id:"FLU05-Q06",skill:"Combined Re, f, and head loss",difficulty:"Hard",prompt:"Water (ρ=1000 kg/m³, μ=0.001 Pa·s) flows at 0.1 m/s through a 0.01 m diameter tube, 5 m long. Find the friction head loss.",choices:["0.0163 m","0.0051 m","0.163 m","0.00163 m"],answer:0,explanation:"The friction head loss is about 0.0163 m.",solution:"Step 1 — Check the regime: Re=ρVD/μ=1000×0.1×0.01/0.001=1000, which is laminar.\nStep 2 — Laminar friction factor: f=64/Re=64/1000=0.064.\nStep 3 — L/D=5/0.01=500; V²/2g=0.01/19.62=0.00051.\nStep 4 — hf=0.064×500×0.00051.\nFinal answer: 0.0163 m.",trap:"0.0051 m comes from assuming a typical turbulent friction factor (about 0.02) instead of first checking Re and using the laminar formula f=64/Re, which gives 0.064 here.",repair:"Always compute Reynolds number first — never assume a 'typical' turbulent f without confirming the flow is actually turbulent."},
{id:"FLU05-Q07",skill:"Reynolds number — solve for velocity",difficulty:"Medium",prompt:"Water (ν=1×10⁻⁶ m²/s) flows through a 0.025 m diameter pipe. Find the maximum velocity for which the flow remains laminar (critical Re=2300).",choices:["0.092 m/s","0.0023 m/s","10.87 m/s","0.230 m/s"],answer:0,explanation:"The maximum laminar velocity is about 0.092 m/s.",solution:"Step 1 — Rearrange Re=VD/ν to solve for V: V=Re·ν/D.\nStep 2 — Substitute: V=2300×0.000001/0.025.\nStep 3 — Numerator: 2300×0.000001=0.0023.\nStep 4 — V=0.0023/0.025.\nFinal answer: 0.092 m/s.",trap:"0.0023 m/s comes from computing Re×ν correctly but forgetting to divide by the diameter D.",repair:"Rearranging Re=VD/ν for V requires dividing by D — don't stop the algebra one step early."},
{id:"FLU05-Q08",skill:"Laminar friction factor behavior",difficulty:"Easy",prompt:"For fully developed laminar flow in a circular pipe, how does the Darcy friction factor f vary with Reynolds number?",choices:["f=64/Re, decreasing as Re increases","f is constant regardless of Re","f increases linearly with Re","f depends only on pipe roughness"],answer:0,explanation:"For laminar flow, f=64/Re, so f decreases as Re increases.",solution:"Step 1 — Recall the laminar friction factor formula: f=64/Re.\nStep 2 — As Re increases, f decreases proportionally (inverse relationship).\nFinal answer: f=64/Re, decreasing as Re increases.",trap:"Claiming f depends on pipe roughness confuses laminar flow (roughness-independent) with turbulent flow, where roughness matters via the Moody chart.",repair:"Laminar friction factor depends only on Re — roughness only enters the picture once the flow becomes turbulent."},
{id:"FLU05-Q09",skill:"Design — maximum pipe length",difficulty:"Hard",prompt:"Water flows at 2.5 m/s through a 0.08 m diameter pipe with friction factor f=0.025. If the maximum allowable friction head loss is 3.0 m, find the longest permissible pipe length (neglect minor losses).",choices:["30.1 m","75.3 m","15.1 m","60.3 m"],answer:0,explanation:"The maximum pipe length is about 30.1 m.",solution:"Step 1 — Rearrange hf=f(L/D)(V²/2g) to solve for L: L=hf·D·2g/(f·V²).\nStep 2 — Numerator: 3.0×0.08×19.62=4.7088.\nStep 3 — Denominator: 0.025×2.5²=0.025×6.25=0.15625.\nStep 4 — L=4.7088/0.15625.\nFinal answer: 30.1 m.",trap:"75.3 m comes from using V instead of V² in the denominator, forgetting that velocity head requires the square of velocity.",repair:"When rearranging the Darcy-Weisbach equation, keep V² intact — don't accidentally drop the square during algebra."},
{id:"FLU05-Q10",skill:"Minor loss calculation",difficulty:"Medium",prompt:"A sudden pipe expansion has a minor loss coefficient K=0.36 based on the upstream velocity of 5 m/s. Find the minor head loss.",choices:["0.459 m","9.00 m","0.229 m","0.918 m"],answer:0,explanation:"The minor head loss is about 0.459 m.",solution:"Step 1 — Use hminor=K(V²/2g).\nStep 2 — V²=25; 2g=19.62.\nStep 3 — V²/2g=25/19.62=1.274.\nStep 4 — hminor=0.36×1.274.\nFinal answer: 0.459 m.",trap:"9.00 m comes from computing K×V² and forgetting to divide by 2g.",repair:"Minor losses always include the full velocity head V²/2g — the 2g in the denominator is easy to drop by mistake."}
];

export const internalFlowModule:StudyModule={id:"FLU-05",subjectId:"fluid-mechanics",sectionId:"internal-flow",title:"Internal Flow and Losses",lessons:lessonsInternal,flashcards:flashcardsInternal,questions:questionsInternal};

// ---------- FLU-06: Pumps and Fluid Machinery ----------

const lessonsPumps=[
{title:"Pump head and power",body:"A pump adds head H to the fluid passing through it. The hydraulic (water) power delivered is P=ρgQH; the shaft (brake) power the driver must supply is larger, P/η, since some input energy is lost to mechanical and hydraulic inefficiencies."},
{title:"Pump efficiency",body:"Efficiency η=Phydraulic/Pshaft is always less than 1 for a real pump. Use it to convert between the useful power delivered to the fluid and the power the motor or engine must actually supply — dividing by η, not multiplying, gives the larger shaft power."},
{title:"System head requirement",body:"The head a pump must supply equals the static elevation lift plus all friction and minor losses in the piping system at the operating flow rate, from the energy equation: Hpump=Δz+Σhlosses. Forgetting either term underestimates the required pump head."},
{title:"Affinity laws and NPSH",body:"For a given pump at different speeds or with a trimmed impeller: Q scales with N (or D), H scales with N² (or D²), and P scales with N³ (or D³). Separately, net positive suction head available (NPSHA) must exceed NPSH required by the pump to avoid cavitation; NPSHA is reduced by suction lift, suction-line friction losses, and low atmospheric or high vapor pressure."}
];

const flashcardsPumps=[
{front:"Pump hydraulic power",back:"P=ρgQH",note:"This is the power delivered TO the fluid, in watts with SI units."},
{front:"Pump efficiency",back:"η=Phydraulic/Pshaft",note:"Always less than 1 — shaft power exceeds hydraulic power."},
{front:"Shaft (brake) power",back:"Pshaft=ρgQH/η",note:"Divide by η to get the larger required input power."},
{front:"System head requirement",back:"Hpump=static lift+Σlosses",note:"Include BOTH elevation change and friction/minor losses."},
{front:"Affinity laws (speed)",back:"Q∝N, H∝N², P∝N³",note:"Don't mix up the exponents — power scales fastest with speed."},
{front:"Affinity laws (impeller diameter)",back:"Q∝D, H∝D², P∝D³",note:"Same exponent pattern as speed, applied to impeller trim."},
{front:"NPSH rule",back:"NPSHavailable must exceed NPSHrequired",note:"Otherwise the pump cavitates — check this before increasing suction lift."},
{front:"Parallel vs. series pumps",back:"Parallel: same head, flows add. Series: same flow, heads add.",note:"Match the arrangement to which quantity actually combines."}
];

const questionsPumps:Question[]=[
{id:"FLU06-Q01",skill:"Pump shaft power",difficulty:"Medium",prompt:"A pump delivers 0.05 m³/s of water (ρ=1000 kg/m³) against a head of 20 m, at 75% efficiency. Find the required shaft power.",choices:["13.08 kW","9.81 kW","7.36 kW","26.16 kW"],answer:0,explanation:"The required shaft power is about 13.08 kW.",solution:"Step 1 — Hydraulic power: Phydraulic=ρgQH=1000×9.81×0.05×20=9810 W.\nStep 2 — Shaft power: Pshaft=Phydraulic/η=9810/0.75.\nFinal answer: 13.08 kW.",trap:"9.81 kW reports the hydraulic power and forgets to divide by the pump's efficiency to get the actual shaft input power.",repair:"Shaft power is always LARGER than hydraulic power — divide by η, don't just report ρgQH."},
{id:"FLU06-Q02",skill:"Pump efficiency",difficulty:"Easy",prompt:"A pump has a hydraulic power output of 8 kW and a shaft power input of 10 kW. Find its efficiency.",choices:["80%","125%","20%","8%"],answer:0,explanation:"The pump efficiency is 80%.",solution:"Step 1 — Use η=Phydraulic/Pshaft.\nStep 2 — Substitute: η=8/10.\nFinal answer: 80%.",trap:"125% comes from inverting the ratio (10/8) instead of dividing hydraulic power by shaft power.",repair:"Efficiency is always output over input — hydraulic power (output) divided by shaft power (input), and it must be less than 100%."},
{id:"FLU06-Q03",skill:"Pump head from pressure rise",difficulty:"Medium",prompt:"A pump raises water pressure from 100 kPa to 550 kPa. The pipe diameter and elevation are the same on both sides. Find the head added by the pump.",choices:["45.9 m","0.046 m","4.59 m","458.7 m"],answer:0,explanation:"The pump adds about 45.9 m of head.",solution:"Step 1 — With equal velocity and elevation, pump head equals the pressure rise divided by ρg: H=Δp/ρg.\nStep 2 — Convert pressure rise to Pa: Δp=550000−100000=450000 Pa.\nStep 3 — H=450000/(1000×9.81)=450000/9810.\nFinal answer: 45.9 m.",trap:"0.046 m comes from using the pressure rise in kPa (450) directly in the formula instead of converting to Pa (450,000) first.",repair:"Always convert pressure to Pa (base SI units) before dividing by ρg — mixing kPa into an SI formula shrinks the answer by 1000×."},
{id:"FLU06-Q04",skill:"Affinity laws — power",difficulty:"Hard",prompt:"A pump at 1750 rpm delivers water requiring 4 kW of shaft power. If the pump speed is increased to 2000 rpm (same impeller), find the new required power using the affinity laws.",choices:["5.97 kW","5.22 kW","4.57 kW","2.68 kW"],answer:0,explanation:"The new required power is about 5.97 kW.",solution:"Step 1 — Affinity law for power: P2=P1(N2/N1)³.\nStep 2 — Speed ratio: N2/N1=2000/1750=1.1429.\nStep 3 — Cube the ratio: (1.1429)³≈1.4927.\nStep 4 — P2=4×1.4927.\nFinal answer: 5.97 kW.",trap:"5.22 kW comes from squaring the speed ratio (the exponent used for HEAD, N²) instead of cubing it (the correct exponent for POWER, N³).",repair:"Memorize all three affinity-law exponents together: Q∝N¹, H∝N², P∝N³ — mixing them up is the most common mistake."},
{id:"FLU06-Q05",skill:"NPSH available",difficulty:"Hard",prompt:"A pump draws water from a source where atmospheric pressure is 101.3 kPa and the water's vapor pressure is 2.3 kPa. The pump sits 3.0 m above the source (static suction lift), and suction-line friction losses are 0.5 m. Find the NPSH available.",choices:["6.59 m","6.83 m","10.09 m","7.09 m"],answer:0,explanation:"The NPSH available is about 6.59 m.",solution:"Step 1 — Use NPSHA=(patm−pv)/ρg−hs−hf.\nStep 2 — Pressure term: (101300−2300)/9810=99000/9810=10.09 m.\nStep 3 — Subtract suction lift and friction loss: 10.09−3.0−0.5.\nFinal answer: 6.59 m.",trap:"10.09 m comes from computing the pressure term correctly but forgetting to subtract both the static suction lift and the suction-line friction loss.",repair:"NPSH available has four terms — never stop after the pressure term; subtract both the suction lift AND the friction loss."},
{id:"FLU06-Q06",skill:"Pump performance curve",difficulty:"Easy",prompt:"A typical centrifugal pump's performance curve shows head as flow rate increases:",choices:["Decreasing head as flow rate increases","Increasing head as flow rate increases","Constant head regardless of flow rate","Head independent of flow rate entirely"],answer:0,explanation:"Centrifugal pump head decreases as flow rate increases, following the characteristic downward-sloping curve.",solution:"Step 1 — Recall the shape of a typical centrifugal pump curve: head is highest near shutoff (zero flow) and falls as flow rate increases.\nFinal answer: Head decreases as flow rate increases.",trap:"Claiming head is constant confuses a centrifugal pump with an idealized constant-head source — real pump curves always slope downward.",repair:"Picture the standard pump curve shape: head drops as flow rate rises, right up until it eventually reaches zero head at maximum flow."},
{id:"FLU06-Q07",skill:"Pumps in parallel",difficulty:"Easy",prompt:"Two identical centrifugal pumps, each delivering 0.025 m³/s at a head of 30 m, are connected in parallel, with the combined system operating at the same 30 m head. Find the total flow rate delivered.",choices:["0.05 m³/s","0.025 m³/s","0.0125 m³/s","0.075 m³/s"],answer:0,explanation:"The total flow rate is 0.05 m³/s.",solution:"Step 1 — In parallel, pumps share the same head and their flow rates add.\nStep 2 — Qtotal=Q1+Q2=0.025+0.025.\nFinal answer: 0.05 m³/s.",trap:"0.025 m³/s reports a single pump's flow rate, as if adding a second pump in parallel didn't increase the total flow.",repair:"Parallel pumps at the same head ADD their flow rates — that's the entire point of a parallel arrangement."},
{id:"FLU06-Q08",skill:"Affinity laws — impeller trim",difficulty:"Medium",prompt:"A pump's impeller is trimmed from 250 mm to 225 mm at constant speed. If the original head was 40 m, find the new head using the affinity laws (H∝D²).",choices:["32.4 m","36.0 m","29.2 m","40.0 m"],answer:0,explanation:"The new head is about 32.4 m.",solution:"Step 1 — Diameter ratio: D2/D1=225/250=0.90.\nStep 2 — Affinity law for head: H2=H1(D2/D1)².\nStep 3 — (0.90)²=0.81.\nStep 4 — H2=40×0.81.\nFinal answer: 32.4 m.",trap:"36.0 m comes from scaling the head by the diameter ratio directly (linearly) instead of squaring it as the affinity law requires.",repair:"Head scales with the SQUARE of the diameter (or speed) ratio — always square before multiplying."},
{id:"FLU06-Q09",skill:"System head and pump power",difficulty:"Hard",prompt:"A pump delivers 0.04 m³/s of water to a tank 25 m higher than the source. Friction and minor losses at this flow rate total 6 m. Pump efficiency is 70%. Find the required shaft power.",choices:["17.38 kW","14.01 kW","12.16 kW","3.36 kW"],answer:0,explanation:"The required shaft power is about 17.38 kW.",solution:"Step 1 — Total pump head: H=static lift+losses=25+6=31 m.\nStep 2 — Hydraulic power: Phydraulic=ρgQH=1000×9.81×0.04×31=12164.4 W.\nStep 3 — Shaft power: Pshaft=Phydraulic/η=12164.4/0.70.\nFinal answer: 17.38 kW.",trap:"14.01 kW comes from using only the 25 m static lift and forgetting to add the 6 m of friction and minor losses to the required pump head.",repair:"The pump must overcome BOTH the elevation lift AND all system losses — always add them together for the total required head."},
{id:"FLU06-Q10",skill:"Pump head from shaft power",difficulty:"Medium",prompt:"A pump delivers 0.015 m³/s of water and receives 6.0 kW of shaft power at 65% efficiency. Find the head added to the water.",choices:["26.5 m","40.8 m","62.7 m","13.3 m"],answer:0,explanation:"The head added is about 26.5 m.",solution:"Step 1 — Hydraulic power: Phydraulic=η×Pshaft=0.65×6000=3900 W.\nStep 2 — Use Phydraulic=ρgQH to solve for H: H=Phydraulic/(ρgQ).\nStep 3 — ρgQ=1000×9.81×0.015=147.15.\nStep 4 — H=3900/147.15.\nFinal answer: 26.5 m.",trap:"40.8 m comes from using the full shaft power (6000 W) as if it were the hydraulic power, forgetting to first multiply by the efficiency.",repair:"Only the hydraulic power (η×Pshaft) goes into the head equation — the raw shaft power overstates what's actually delivered to the fluid."}
];

export const pumpsModule:StudyModule={id:"FLU-06",subjectId:"fluid-mechanics",sectionId:"pumps",title:"Pumps and Fluid Machinery",lessons:lessonsPumps,flashcards:flashcardsPumps,questions:questionsPumps};

